// Exposes product imagery by path relative to the images/ folder, e.g.
// img('TV/tv.jpg') or a slide video img('Slides/Home/tv.mp4').
//
// IMPORTANT: the app serves ONLY web-optimized copies from src/images-web/
// (generated by `npm run assets` -> scripts/optimize-images.mjs +
// optimize-videos.mjs). The multi-hundred-MB originals under src/images/ are
// the source of truth and are deliberately NOT globbed here — eagerly bundling
// them would ship the full-resolution masters (some 40 MB each) to the browser
// and into dist/. Lookups are extension-agnostic, so a request for any original
// extension (img('foo/bar.png')) resolves to images-web/foo/bar.webp.
//
// If you add a new image under src/images/, run `npm run assets` (predev and
// prebuild do this automatically) to generate its optimized copy.
const webModules = import.meta.glob('../images-web/**/*.{webp,WEBP,mp4,webm,MP4,WEBM,gif,GIF}', {
  eager: true,
  query: '?url',
  import: 'default'
}) as Record<string, string>

const stripExt = (p: string): string => p.replace(/\.[^./]+$/, '')
const relKey = (key: string, marker: string): string | null => {
  const idx = key.indexOf(marker)
  return idx >= 0 ? key.slice(idx + marker.length) : null
}

// Optimized assets, keyed by extension-stripped, lower-cased relative path so a
// request for any original extension resolves to the .webp / .mp4 copy. Keys are
// lower-cased so lookups are case-insensitive — the optimizer's output filename
// case can drift from the source (esp. on case-insensitive filesystems).
const webMap: Record<string, string> = {}
for (const [key, url] of Object.entries(webModules)) {
  const rel = relKey(key, '/images-web/')
  if (rel) webMap[stripExt(rel).toLowerCase()] = url
}

const resolve = (relativePath: string): string | undefined => webMap[stripExt(relativePath).toLowerCase()]

// Category banner images live under src/images/Slides/<Folder>/ (optimized into
// src/images-web/Slides/<Folder>/). Each file becomes a slide in that category's
// hero slider — drop images in, run `npm run assets`, and they appear
// automatically, sorted by filename. Videos (.mp4/.webm) are supported.
export interface SlideAsset {
  url: string
  file: string
  video: boolean
}

export const slideBanners: Record<string, SlideAsset[]> = {}
for (const [key, url] of Object.entries(webModules)) {
  const m = key.match(/\/Slides\/([^/]+)\/([^/]+)$/)
  if (!m) continue
  const [, folder, file] = m
  const video = /\.(mp4|webm)$/i.test(file)
  ;(slideBanners[folder] ??= []).push({ url, file, video })
}
for (const list of Object.values(slideBanners)) {
  list.sort((a, b) => a.file.localeCompare(b.file, undefined, { numeric: true }))
}

// Top-Freezer refrigerator photos, auto-discovered from
// src/images/Refrigerator/Top freezer/ so new files appear without editing the
// catalog. RFT is grouped by size folder (UN-RFT380 …); TITAN is a flat list of
// its RF463 colour variants. Each photo notes its model code and whether it's an
// open-door shot ("<model> open"). Non-product helper files (not "UN-…") skip.
export interface TFPhoto {
  url: string
  model: string // e.g. 'UN-RFT380BG'
  open: boolean // true for the open-door variant
}
export const topFreezerRFT: Record<string, TFPhoto[]> = {}
export const topFreezerTitan: TFPhoto[] = []
for (const [key, url] of Object.entries(webModules)) {
  // RFT holds the colour finishes; Gold holds a gold finish for the same sizes —
  // both group by the size folder so gold joins that size's gallery.
  const rft = key.match(/\/Top freezer\/(RFT|Gold)\/([^/]+)\/([^/]+)\.[^./]+$/)
  if (rft) {
    const [, finish, folder, base] = rft
    const open = / open$/i.test(base)
    let model = base.replace(/ open$/i, '').trim()
    if (!model.toUpperCase().startsWith('UN-')) continue // skip helper images
    if (finish === 'Gold') model = `${model} Gold`
    ;(topFreezerRFT[folder] ??= []).push({ url, model, open })
    continue
  }
  const titan = key.match(/\/Top freezer\/TITAN\/[^/]+\/([^/]+)\.[^./]+$/)
  if (titan) {
    const model = titan[1].replace(/ TITAN$/i, '').trim()
    topFreezerTitan.push({ url, model, open: false })
  }
}
// Closed shots before their open-door counterparts, ordered by model code.
for (const list of Object.values(topFreezerRFT)) {
  list.sort((a, b) => a.model.localeCompare(b.model, undefined, { numeric: true }) || Number(a.open) - Number(b.open))
}
topFreezerTitan.sort((a, b) => a.model.localeCompare(b.model, undefined, { numeric: true }))

// Washing-machine photos, auto-discovered from src/images/wm/. Each model is the
// leaf folder that directly contains its photos (depth varies: some sit under a
// family folder like maxpro/, VEVO models under a pair folder, OPAL directly).
// Photos are ordered front-facing-closed first so the card shows a clean hero.
export type WMSubtype = 'Front Load' | 'Twin Tub' | 'Top Load'
export interface WMModel {
  folder: string // leaf folder = model code, e.g. 'UN-8TBL MAXPRO', 'WM_OPAL'
  subtype: WMSubtype
  photos: string[] // ordered urls
}
export const washingMachines: WMModel[] = []
{
  const rank = (file: string): number => {
    const s = file.toLowerCase()
    if (/control|panel|控板/.test(s)) return 8
    if (/inside/.test(s)) return 7
    if (/open|opening|开门/.test(s)) return 6
    if (/closed.*front|front.*closed|正面关门/.test(s)) return 0
    if (/\bfront\b|正面/.test(s)) return 1
    if (/left|right|side|侧/.test(s)) return 4
    return 3
  }
  const groups = new Map<string, { folder: string; subtype: WMSubtype; items: { url: string; file: string }[] }>()
  for (const [key, url] of Object.entries(webModules)) {
    const m = key.match(/\/wm\/(front_load|Twin Tub|TOP)\/(.+)$/)
    if (!m) continue
    const subtype: WMSubtype = m[1] === 'front_load' ? 'Front Load' : m[1] === 'TOP' ? 'Top Load' : 'Twin Tub'
    const parts = m[2].split('/')
    const file = parts.pop() as string
    const folder = parts.pop() ?? subtype // leaf folder is the model
    const k = `${subtype}|${folder}`
    if (!groups.has(k)) groups.set(k, { folder, subtype, items: [] })
    groups.get(k)!.items.push({ url, file })
  }
  for (const g of groups.values()) {
    g.items.sort((a, b) => rank(a.file) - rank(b.file) || a.file.localeCompare(b.file, undefined, { numeric: true }))
    washingMachines.push({ folder: g.folder, subtype: g.subtype, photos: g.items.map((i) => i.url) })
  }
  // Front Load before Twin Tub, then by model name.
  washingMachines.sort(
    (a, b) => a.subtype.localeCompare(b.subtype) || a.folder.localeCompare(b.folder, undefined, { numeric: true })
  )
}

// Television photos, auto-discovered from src/images/TV/<model>/. Each model is a
// folder (e.g. 'U5514 VENZA'); photos are ordered front-facing first.
export interface TVModel {
  tech: string // QLED / UHD / FHD — from the parent folder
  folder: string // model code, e.g. 'Q6514 PRO'
  photos: string[]
}
export const televisions: TVModel[] = []
{
  const rank = (file: string): number => {
    if (/uneva/i.test(file)) return -1 // Uneva-branded hero shots first
    if (/正透视|正面|\bfront\b|色彩|scene|untitled_0000|\(1\)/i.test(file)) return 0
    if (/后视|顶视|底|背|细节|back|top|bottom|rear|detail/i.test(file)) return 5
    return 2
  }
  const groups = new Map<string, { tech: string; model: string; items: { url: string; file: string }[] }>()
  for (const [key, url] of Object.entries(webModules)) {
    const m = key.match(/\/TV\/([^/]+)\/([^/]+)\/([^/]+)\.[^./]+$/)
    if (!m) continue
    const [, tech, model, base] = m
    const k = `${tech}|${model}`
    if (!groups.has(k)) groups.set(k, { tech, model, items: [] })
    groups.get(k)!.items.push({ url, file: base })
  }
  for (const { tech, model, items } of groups.values()) {
    items.sort((a, b) => rank(a.file) - rank(b.file) || a.file.localeCompare(b.file, undefined, { numeric: true }))
    // Normalize the folder name (some contain a non-breaking space) so model
    // codes match the catalog's spec-record keys and series-splitting works.
    const clean = (s: string) => s.replace(/ /g, ' ').replace(/\s+/g, ' ').trim()
    televisions.push({ tech: clean(tech), folder: clean(model), photos: items.map((i) => i.url) })
  }
  televisions.sort((a, b) => a.folder.localeCompare(b.folder, undefined, { numeric: true }))
}

// Microwave photos, auto-discovered from src/images/Microwave/<family>/<model>/.
// The hero shot is the file whose name matches the model folder
// (e.g. UN-MV42GHB/UN-MV42GHB.png); the remaining Image_* shots fill the
// gallery. Drop photos in, run `npm run assets`, and the model appears.
export interface MicrowaveModel {
  family: string // e.g. 'MV42'
  folder: string // model code = folder name, e.g. 'UN-MV42GHB'
  photos: string[] // ordered urls, hero (named after the folder) first
}
export const microwaves: MicrowaveModel[] = []
{
  const groups = new Map<string, { family: string; folder: string; items: { url: string; file: string }[] }>()
  for (const [key, url] of Object.entries(webModules)) {
    const m = key.match(/\/Microwave\/([^/]+)\/([^/]+)\/([^/]+)\.[^./]+$/)
    if (!m) continue
    const [, family, folder, base] = m
    const k = `${family}|${folder}`
    if (!groups.has(k)) groups.set(k, { family, folder, items: [] })
    groups.get(k)!.items.push({ url, file: base })
  }
  for (const g of groups.values()) {
    // Hero first: the file named after the model folder; the rest by filename.
    g.items.sort((a, b) => {
      const ah = a.file.toLowerCase() === g.folder.toLowerCase() ? 0 : 1
      const bh = b.file.toLowerCase() === g.folder.toLowerCase() ? 0 : 1
      return ah - bh || a.file.localeCompare(b.file, undefined, { numeric: true })
    })
    microwaves.push({ family: g.family, folder: g.folder, photos: g.items.map((i) => i.url) })
  }
  microwaves.sort((a, b) => a.folder.localeCompare(b.folder, undefined, { numeric: true }))
}

export function img(relativePath: string): string {
  const url = resolve(relativePath)
  if (!url) {
    console.warn('[assets] image not found (run `npm run assets`?):', relativePath)
    return ''
  }
  return url
}

// Like img() but returns undefined (no warning) when the file is absent.
// Use for optional assets such as a hero video that may not exist yet.
export function optionalImg(relativePath: string): string | undefined {
  return resolve(relativePath)
}
